fn without_details_validate_rows(rows: &[MeasurementRowV1WithoutDetails]) -> Result<()> {
    let mut previous = None;
    for row in rows {
        without_details_validate_row(row, previous)?;
        previous = Some(row);
    }
    Ok(())
}

fn without_details_validate_row(
    row: &MeasurementRowV1WithoutDetails,
    previous: Option<&MeasurementRowV1WithoutDetails>,
) -> Result<()> {
    if row.schema_version != 1 {
        return Err(TransportError::SchemaVersionMismatch {
            observed: row.schema_version,
            expected: 1,
        });
    }
    device_symbol(row.device_ordinal)?;
    interval_symbol(row.interval_ordinal)?;
    validate_finite_f64("value_a", row.value_a)?;
    validate_finite_f64("value_b", row.value_b)?;
    validate_finite_f64("value_c", row.value_c)?;
    validate_finite_f64("value_d", row.value_d)?;
    validate_finite_f64("value_e", row.value_e)?;
    validate_finite_f64("value_f", row.value_f)?;
    validate_finite_f64("value_g", row.value_g)?;
    validate_finite_f64("value_h", row.value_h)?;
    validate_finite_f64("value_i", row.value_i)?;
    validate_finite_f64("value_j", row.value_j)?;
    validate_finite_f64("average_value", row.average_value)?;
    if row.presence_bits & !WITHOUT_DETAILS_PRESENCE_ALLOWED_MASK != 0 {
        return Err(TransportError::InvalidPresenceBits(row.presence_bits));
    }
    if row.presence_bits & WITHOUT_DETAILS_PRESENCE_AVERAGE_VALUE == 0 && row.average_value != 0.0 {
        return Err(TransportError::InvalidPresenceBits(row.presence_bits));
    }
    if row.presence_bits & WITHOUT_DETAILS_PRESENCE_SAMPLE_COUNT == 0 && row.sample_count != 0 {
        return Err(TransportError::InvalidPresenceBits(row.presence_bits));
    }
    if row.presence_bits & WITHOUT_DETAILS_PRESENCE_AGE_MS == 0 && row.age_ms != 0 {
        return Err(TransportError::InvalidPresenceBits(row.presence_bits));
    }
    if previous.is_some_and(|prev| {
        (row.device_ordinal, row.interval_ordinal, row.recorded_at_ms)
            < (
                prev.device_ordinal,
                prev.interval_ordinal,
                prev.recorded_at_ms,
            )
    }) {
        return Err(TransportError::InvalidTimeGrid(
            "key order regression".to_string(),
        ));
    }
    Ok(())
}

