fn without_details_validate_archived_payload(
    archived: &ArchivedMeasurementResponseV1PayloadWithoutDetails,
    expected_rows: u64,
) -> Result<()> {
    if archived.schema_version.to_native() != WITHOUT_DETAILS_SCHEMA_VERSION_VALUE {
        return Err(TransportError::SchemaVersionMismatch {
            observed: archived.schema_version.to_native(),
            expected: WITHOUT_DETAILS_SCHEMA_VERSION_VALUE,
        });
    }
    let expected = usize::try_from(expected_rows)
        .map_err(|err| TransportError::MalformedArchive(err.to_string()))?;
    if archived.rows.len() != expected {
        return Err(TransportError::RowCountMismatch {
            observed: archived.rows.len(),
            expected: expected_rows,
        });
    }
    without_details_validate_archived_rows(archived)
}

fn without_details_validate_archived_rows(
    archived: &ArchivedMeasurementResponseV1PayloadWithoutDetails,
) -> Result<()> {
    let mut previous = None;
    for archived_row in archived.rows.iter() {
        let row = without_details_row_from_archived(archived_row);
        without_details_validate_row(&row, previous.as_ref())?;
        previous = Some(row);
    }
    Ok(())
}

fn without_details_inspect_archived_rows(
    archived: &ArchivedMeasurementResponseV1PayloadWithoutDetails,
) -> Result<BinaryInspection> {
    let mut previous = None;
    let mut semantic_checksum = fnv1a64("mbt.example.measurement.v1.without_details".as_bytes());
    let mut minimal_projection_checksum = semantic_checksum;
    for archived_row in archived.rows.iter() {
        let row = without_details_row_from_archived(archived_row);
        without_details_validate_row(&row, previous.as_ref())?;
        semantic_checksum =
            without_details_checksum_archived_row(semantic_checksum, archived_row, true);
        minimal_projection_checksum = without_details_minimal_projection_archived_row(
            minimal_projection_checksum,
            archived_row,
        );
        previous = Some(row);
    }
    Ok(BinaryInspection {
        row_count: archived.rows.len(),
        semantic_checksum,
        minimal_projection_checksum,
    })
}

