const VALUES_ONLY_GENERATED_SCHEMA_HASH: u64 = 2627786485738809661;
const VALUES_ONLY_TRANSPORT_NAME: &str = "mbt.example.measurement.v1.values_only";
const VALUES_ONLY_SCHEMA_HEADER: SchemaHeaderSpec = SchemaHeaderSpec {
    schema_id: VALUES_ONLY_SCHEMA_ID,
    schema_version: VALUES_ONLY_SCHEMA_VERSION,
    schema_hash: VALUES_ONLY_GENERATED_SCHEMA_HASH,
};

