#[derive(Clone, Archive, RkyvSerialize)]
pub struct MeasurementRowV1ValuesOnly {
    pub schema_version: u16,
    pub device_ordinal: u16,
    pub interval_ordinal: u16,
    pub started_at_ms: i64,
    pub recorded_at_ms: i64,
    pub value_a: f64,
    pub value_b: f64,
    pub value_c: f64,
    pub value_d: f64,
    pub value_e: f64,
}

fn values_only_validate_rows(rows: &[MeasurementRowV1ValuesOnly]) -> Result<()> {
    let mut previous = None;
    for row in rows {
        values_only_validate_row(row, previous)?;
        previous = Some(row);
    }
    Ok(())
}

fn values_only_validate_row(
    row: &MeasurementRowV1ValuesOnly,
    previous: Option<&MeasurementRowV1ValuesOnly>,
) -> Result<()> {
    if row.schema_version != 1 {
        return Err(TransportError::SchemaVersionMismatch {
            observed: row.schema_version,
            expected: 1,
        });
    }
    device_symbol(row.device_ordinal)?;
    interval_symbol(row.interval_ordinal)?;
    validate_finite_f64("value_a", row.value_a)?;
    validate_finite_f64("value_b", row.value_b)?;
    validate_finite_f64("value_c", row.value_c)?;
    validate_finite_f64("value_d", row.value_d)?;
    validate_finite_f64("value_e", row.value_e)?;
    if previous.is_some_and(|prev| {
        (row.device_ordinal, row.interval_ordinal, row.recorded_at_ms)
            < (
                prev.device_ordinal,
                prev.interval_ordinal,
                prev.recorded_at_ms,
            )
    }) {
        return Err(TransportError::InvalidTimeGrid(
            "key order regression".to_string(),
        ));
    }
    Ok(())
}

fn values_only_checksum_archived_row(
    mut checksum: u64,
    row: &<MeasurementRowV1ValuesOnly as Archive>::Archived,
    include_metadata: bool,
) -> u64 {
    checksum = update_u16(checksum, row.schema_version.to_native());
    checksum = update_u16(checksum, row.device_ordinal.to_native());
    checksum = update_u16(checksum, row.interval_ordinal.to_native());
    checksum = update_i64(checksum, row.started_at_ms.to_native());
    checksum = update_i64(checksum, row.recorded_at_ms.to_native());
    checksum = update_f64(checksum, row.value_a.to_native());
    checksum = update_f64(checksum, row.value_b.to_native());
    checksum = update_f64(checksum, row.value_c.to_native());
    checksum = update_f64(checksum, row.value_d.to_native());
    checksum = update_f64(checksum, row.value_e.to_native());
    let _ = include_metadata;
    checksum
}

fn values_only_minimal_projection_archived_row(
    mut checksum: u64,
    row: &<MeasurementRowV1ValuesOnly as Archive>::Archived,
) -> u64 {
    checksum = update_u16(checksum, row.schema_version.to_native());
    checksum = update_u16(checksum, row.device_ordinal.to_native());
    checksum = update_u16(checksum, row.interval_ordinal.to_native());
    checksum = update_i64(checksum, row.started_at_ms.to_native());
    checksum = update_i64(checksum, row.recorded_at_ms.to_native());
    checksum = update_f64(checksum, row.value_a.to_native());
    checksum = update_f64(checksum, row.value_b.to_native());
    checksum = update_f64(checksum, row.value_c.to_native());
    checksum = update_f64(checksum, row.value_d.to_native());
    checksum = update_f64(checksum, row.value_e.to_native());
    checksum
}

pub struct MeasurementV1ValuesOnly;

impl MeasurementV1ValuesOnly {
    pub const SCHEMA_ID: u32 = VALUES_ONLY_SCHEMA_ID;
    pub const SCHEMA_VERSION: u16 = VALUES_ONLY_SCHEMA_VERSION;
    pub const SCHEMA_HASH: u64 = VALUES_ONLY_GENERATED_SCHEMA_HASH;
    pub const TRANSPORT_NAME: &'static str = VALUES_ONLY_TRANSPORT_NAME;

    pub fn header_spec() -> SchemaHeaderSpec {
        VALUES_ONLY_SCHEMA_HEADER
    }

    pub fn encode(
        rows: &[MeasurementRowV1ValuesOnly],
        max_response_bytes: usize,
    ) -> Result<Vec<u8>> {
        Self::encode_owned(rows.to_vec(), max_response_bytes)
    }

    pub fn encode_owned(
        rows: Vec<MeasurementRowV1ValuesOnly>,
        max_response_bytes: usize,
    ) -> Result<Vec<u8>> {
        values_only_validate_rows(&rows)?;
        let row_count = rows.len();
        let payload = MeasurementResponseV1PayloadValuesOnly {
            schema_version: VALUES_ONLY_SCHEMA_VERSION_VALUE,
            rows,
        };
        let payload_bytes = rkyv::to_bytes::<RkyvError>(&payload)
            .map_err(|err| TransportError::MalformedArchive(err.to_string()))?;
        let payload_len = payload_bytes.len();
        let total_len =
            HEADER_LEN
                .checked_add(payload_len)
                .ok_or(TransportError::ResponseTooLarge {
                    observed: usize::MAX,
                    cap: max_response_bytes,
                })?;
        if total_len > max_response_bytes {
            return Err(TransportError::ResponseTooLarge {
                observed: total_len,
                cap: max_response_bytes,
            });
        }
        let header = TransportHeader::new_with_schema(
            Self::header_spec(),
            row_count as u64,
            payload_len as u64,
            fnv1a64(&payload_bytes),
        );
        let mut header_bytes = [0_u8; HEADER_LEN];
        encode_header(&header, &mut header_bytes);
        let mut out = Vec::with_capacity(total_len);
        out.extend_from_slice(&header_bytes);
        out.extend_from_slice(&payload_bytes);
        Ok(out)
    }

    pub fn access(bytes: &[u8]) -> Result<MeasurementV1ValuesOnlyView<'_>> {
        Ok(MeasurementV1ValuesOnlyView {
            archived: Self::access_archived(bytes)?,
        })
    }

    pub(crate) fn access_archived(
        bytes: &[u8],
    ) -> Result<&ArchivedMeasurementResponseV1PayloadValuesOnly> {
        let (header, payload) = decode_payload(bytes, Self::header_spec())?;
        let archived =
            rkyv::access::<ArchivedMeasurementResponseV1PayloadValuesOnly, RkyvError>(payload)
                .map_err(|err| TransportError::MalformedArchive(err.to_string()))?;
        values_only_validate_archived_payload(archived, header.row_count)?;
        Ok(archived)
    }

    /// Returns an archived payload view for immutable bytes already validated for this schema.
    ///
    /// # Safety
    /// The caller guarantees that bytes were previously accepted by checked MBT access
    /// for this schema and then stored or transported without mutation.
    pub unsafe fn access_archived_trusted_unchecked(
        bytes: &[u8],
    ) -> Result<&ArchivedMeasurementResponseV1PayloadValuesOnly> {
        let payload = trusted_payload_for_schema(bytes, Self::header_spec())?;
        Ok(unsafe {
            rkyv::access_unchecked::<ArchivedMeasurementResponseV1PayloadValuesOnly>(payload)
        })
    }

    pub fn inspect(bytes: &[u8]) -> Result<BinaryInspection> {
        values_only_inspect_archived_rows(Self::access_archived(bytes)?)
    }
}

