fn values_only_validate_archived_payload(
    archived: &ArchivedMeasurementResponseV1PayloadValuesOnly,
    expected_rows: u64,
) -> Result<()> {
    if archived.schema_version.to_native() != VALUES_ONLY_SCHEMA_VERSION_VALUE {
        return Err(TransportError::SchemaVersionMismatch {
            observed: archived.schema_version.to_native(),
            expected: VALUES_ONLY_SCHEMA_VERSION_VALUE,
        });
    }
    let expected = usize::try_from(expected_rows)
        .map_err(|err| TransportError::MalformedArchive(err.to_string()))?;
    if archived.rows.len() != expected {
        return Err(TransportError::RowCountMismatch {
            observed: archived.rows.len(),
            expected: expected_rows,
        });
    }
    values_only_validate_archived_rows(archived)
}

fn values_only_validate_archived_rows(
    archived: &ArchivedMeasurementResponseV1PayloadValuesOnly,
) -> Result<()> {
    let mut previous = None;
    for archived_row in archived.rows.iter() {
        let row = values_only_row_from_archived(archived_row);
        values_only_validate_row(&row, previous.as_ref())?;
        previous = Some(row);
    }
    Ok(())
}

fn values_only_inspect_archived_rows(
    archived: &ArchivedMeasurementResponseV1PayloadValuesOnly,
) -> Result<BinaryInspection> {
    let mut previous = None;
    let mut semantic_checksum = fnv1a64("mbt.example.measurement.v1.values_only".as_bytes());
    let mut minimal_projection_checksum = semantic_checksum;
    for archived_row in archived.rows.iter() {
        let row = values_only_row_from_archived(archived_row);
        values_only_validate_row(&row, previous.as_ref())?;
        semantic_checksum =
            values_only_checksum_archived_row(semantic_checksum, archived_row, true);
        minimal_projection_checksum =
            values_only_minimal_projection_archived_row(minimal_projection_checksum, archived_row);
        previous = Some(row);
    }
    Ok(BinaryInspection {
        row_count: archived.rows.len(),
        semantic_checksum,
        minimal_projection_checksum,
    })
}

fn values_only_row_from_archived(
    row: &<MeasurementRowV1ValuesOnly as Archive>::Archived,
) -> MeasurementRowV1ValuesOnly {
    MeasurementRowV1ValuesOnly {
        schema_version: row.schema_version.to_native(),
        device_ordinal: row.device_ordinal.to_native(),
        interval_ordinal: row.interval_ordinal.to_native(),
        started_at_ms: row.started_at_ms.to_native(),
        recorded_at_ms: row.recorded_at_ms.to_native(),
        value_a: row.value_a.to_native(),
        value_b: row.value_b.to_native(),
        value_c: row.value_c.to_native(),
        value_d: row.value_d.to_native(),
        value_e: row.value_e.to_native(),
    }
}
